const content=[
 {name:'소개',en:'ABOUT',title:'만드는 사람에 대하여',copy:'관심과 생각, 개발을 대하는 방식.',items:[['경계 없이 만드는 개발자','프론트엔드와 백엔드, 인프라와 실험적인 작업까지. 문제를 해결하는 데 필요한 기술을 탐색합니다.'],['관심에서 시작하는 작업','개인적인 호기심이 어떻게 하나의 결과물로 이어졌는지, 그 과정을 이 공간에 담으려 합니다.']]},
 {name:'프로젝트',en:'PROJECTS',title:'아이디어가 실제로 작동할 때',copy:'직접 만들고, 부딪히고, 개선한 것들.',items:[['01 / 웹 서비스 — 예시','사용자 경험부터 서버 설계까지 연결한 프로젝트를 소개하는 자리입니다.','Frontend','Backend'],['02 / 개발 도구 — 예시','반복되는 작업을 줄이기 위해 만든 도구와 구현 과정을 담습니다.','Automation','Tooling'],['03 / 인터랙티브 실험 — 예시','그래픽과 인터랙션을 탐구한 작은 실험을 모읍니다.','Three.js','Creative coding']]},
 {name:'기술',en:'TOOLKIT',title:'문제에 맞는 도구를 고릅니다',copy:'화면부터 시스템까지, 이어지는 기술.',items:[['Frontend','인터페이스와 인터랙션을 만드는 기술을 정리할 공간입니다.'],['Backend & Infrastructure','서비스의 구조와 운영 경험을 정리할 공간입니다.'],['Experiments','새롭게 탐색하는 기술과 실험을 담을 공간입니다.']]},
 {name:'기록',en:'NOTES',title:'완성된 결과 너머의 생각',copy:'배운 것, 고민한 것, 다음에 시도할 것.',items:[['구현 중에 만난 질문들 — 예시','기술을 선택한 이유와 문제를 해결한 과정을 기록합니다.'],['작은 실험의 기록 — 예시','성공한 시도뿐 아니라, 기대와 달랐던 결과도 남깁니다.']]},
 {name:'연락처',en:'CONTACT',title:'다음 연결을 기다립니다',copy:'이야기와 질문, 함께 만들 가능성.',items:[['GitHub','실제 GitHub 프로필을 연결할 자리입니다.'],['Email','공개할 이메일 주소를 넣을 자리입니다.']]}
];
const $=s=>document.querySelector(s),dialog=$('#detail');let front=0,selectVertex=null,lastFocus=null;
function showFront(i){front=i;const c=content[i];$('#preview-number').textContent=`0${i+1} / ${c.en}`;$('#preview-title').textContent=c.title;$('#preview-copy').textContent=c.copy;document.querySelectorAll('.nav-item').forEach((b,j)=>b.classList.toggle('front',i===j));}
function openDetail(i){lastFocus=document.activeElement;const c=content[i];$('#detail-number').textContent=`0${i+1} / ${c.en}`;$('#detail-title').textContent=c.title;$('#detail-body').innerHTML=c.items.map(([h,p,...tags])=>`<article class="entry"><h3>${h}</h3><p>${p}</p>${tags.map(t=>`<span class="tag">${t}</span>`).join('')}</article>`).join('');dialog.showModal();}
let pending=null;function choose(i){clearTimeout(pending);showFront(i);if(selectVertex){selectVertex(i);pending=setTimeout(()=>openDetail(i),matchMedia('(prefers-reduced-motion: reduce)').matches?0:650);}else openDetail(i);}
document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.id)));$('#preview-open').onclick=()=>choose(front);$('#close').onclick=$('#back').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>lastFocus?.focus());showFront(0);
try{
 const THREE=await import('./vendor/three.module.js');const stage=$('#stage'),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(36,1,.1,100);camera.position.z=7.6;const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));stage.appendChild(renderer.domElement);$('#fallback').remove();
 const group=new THREE.Group();scene.add(group);const geometry=new THREE.IcosahedronGeometry(1.95,0);const edges=new THREE.EdgesGeometry(geometry);group.add(new THREE.LineSegments(edges,new THREE.LineBasicMaterial({color:0x8392ca,transparent:true,opacity:.65})));
 const verts=[];const attr=geometry.attributes.position;for(let i=0;i<attr.count;i++){const v=new THREE.Vector3().fromBufferAttribute(attr,i);if(!verts.some(p=>p.distanceTo(v)<.01))verts.push(v);}verts.forEach(v=>{const dot=new THREE.Mesh(new THREE.SphereGeometry(.022,8,6),new THREE.MeshBasicMaterial({color:0x7587c8}));dot.position.copy(v);group.add(dot);});
 const chosen=[0,2,4,7,10].map(i=>verts[i]);const buttons=chosen.map((v,i)=>{const b=document.createElement('button');b.className='node';b.setAttribute('aria-label',content[i].name+' 열기');b.innerHTML=`<span>${content[i].name}</span>`;b.onclick=()=>choose(i);$('#nodes').appendChild(b);return b;});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches,target=null,drag=null,width=1,height=1,lastTime=0;group.rotation.set(.23,-.48,.08);
 function motionLabel(){$('#motion').textContent=paused?'▷ 회전 시작':'Ⅱ 회전 멈춤';$('#motion').setAttribute('aria-pressed',String(paused));}motionLabel();$('#motion').onclick=()=>{paused=!paused;target=null;motionLabel();};
 selectVertex=i=>{target=new THREE.Quaternion().setFromUnitVectors(chosen[i].clone().normalize(),new THREE.Vector3(0,0,1));paused=true;motionLabel();if(reduced.matches)group.quaternion.copy(target);};
 const resize=()=>{width=stage.clientWidth;height=stage.clientHeight;renderer.setSize(width,height);camera.aspect=width/height;camera.position.z=width<400?9.7:7.6;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(stage);resize();
 stage.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};stage.setPointerCapture(e.pointerId);paused=true;target=null;motionLabel();});stage.addEventListener('pointermove',e=>{if(!drag)return;const q=new THREE.Quaternion().setFromEuler(new THREE.Euler((e.clientY-drag.y)*.006,(e.clientX-drag.x)*.006,0));group.quaternion.premultiply(q);drag={x:e.clientX,y:e.clientY};});const end=()=>drag=null;stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);stage.addEventListener('lostpointercapture',end);
 function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(document.hidden)return;if(target){group.quaternion.slerp(target,1-Math.exp(-7*dt));if(group.quaternion.angleTo(target)<.002)target=null;}else if(!paused&&!dialog.open){group.rotation.y+=dt*.14;group.rotation.x+=dt*.025;}group.updateMatrixWorld();let nearest=0,best=-Infinity;chosen.forEach((v,i)=>{const world=v.clone().applyQuaternion(group.quaternion);if(world.z>best){best=world.z;nearest=i;}const p=world.clone().project(camera);const b=buttons[i];b.style.left=`${(p.x*.5+.5)*width+stage.offsetLeft}px`;b.style.top=`${(-p.y*.5+.5)*height+stage.offsetTop}px`;b.style.opacity=world.z<0?'.4':'1';});buttons.forEach((b,i)=>b.classList.toggle('front',i===nearest));if(!target&&nearest!==front)showFront(nearest);renderer.render(scene,camera);}requestAnimationFrame(frame);
}catch(error){console.error('3D unavailable',error);$('#fallback').textContent='이 환경에서는 3D 화면을 표시할 수 없어요. 메뉴에서 모든 내용을 확인할 수 있습니다.';$('#motion').hidden=true;}
